218:     double entry_price, sl_price, tp1_price, tp2_price, tp3_price, tp4_price, tp5_price;
219:     
220:     // Get previous M5 candle low/high for SL
221:     double prev_m5_low = iLow(_Symbol, PERIOD_M5, 1);
222:     double prev_m5_high = iHigh(_Symbol, PERIOD_M5, 1);
223:     
224:     // Current bid/ask
225:     double bid = SymbolInfoDouble(_Symbol, SYMBOL_BID);
226:     double ask = SymbolInfoDouble(_Symbol, SYMBOL_ASK);
227:     
228:     if(trade_type == 1) {  // BUY
229:         entry_price = ask;
230:         sl_price = prev_m5_low - (SL_Buffer * symInfo.Point());
231:         
232:         // Calculate TP levels based on risk-reward
233:         double risk = entry_price - sl_price;
234:         tp1_price = entry_price + (risk * 2.0);
235:         tp2_price = entry_price + (risk * 3.0);
236:         tp3_price = entry_price + (risk * 5.0);
237:         tp4_price = entry_price + (risk * 10.0);
238:         tp5_price = entry_price + (risk * 15.0);
239:         
240:     } else {  // SELL
241:         entry_price = bid;
242:         sl_price = prev_m5_high + (SL_Buffer * symInfo.Point());
243:         
244:         double risk = sl_price - entry_price;
245:         tp1_price = entry_price - (risk * 2.0);
246:         tp2_price = entry_price - (risk * 3.0);
247:         tp3_price = entry_price - (risk * 5.0);
248:         tp4_price = entry_price - (risk * 10.0);
249:         tp5_price = entry_price - (risk * 15.0);
250:     }
251:     
252:     // Calculate lot size based on risk
253:     double account_balance = AccountInfoDouble(ACCOUNT_BALANCE);
254:     double risk_amount = account_balance * (RiskPercent / 100.0);
255:     double sl_distance = MathAbs(entry_price - sl_price);
256:     double lot_size = CalculateLotSize(risk_amount, sl_distance);
257:     
258:     if(lot_size < symInfo.LotsMin()) {
259:         Print("Lot size too small: ", lot_size);
260:         return;
261:     }
262:     
263:     // Set TP levels in array
264:     tp_levels[0].RR = 2.0;
265:     tp_levels[1].RR = 3.0;
266:     tp_levels[2].RR = 5.0;
267:     tp_levels[3].RR = 10.0;
268:     tp_levels[4].RR = 15.0;
269:     
270:     for(int i = 0; i < 5; i++) {
271:         tp_levels[i].Closed = false;
272:         if(trade_type == 1) {
273:             tp_levels[i].SL_Target = entry_price + ((tp1_price - entry_price) * 0.5 * (tp_levels[i].RR / 2.0));
274:         } else {
275:             tp_levels[i].SL_Target = entry_price - ((entry_price - tp1_price) * 0.5 * (tp_levels[i].RR / 2.0));
276:         }
277:     }
278:     
279:     // Open position
280:     if(trade_type == 1) {
281:         trade.BuyStop(lot_size, entry_price, _Symbol, sl_price, tp5_price, ORDER_TIME_GTC, 0, "XAUUSD Multi-TF Buy");
282:     } else {
283:         trade.SellStop(lot_size, entry_price, _Symbol, sl_price, tp5_price, ORDER_TIME_GTC, 0, "XAUUSD Multi-TF Sell");
