293: double CalculateLotSize(double risk_amount, double sl_distance)
294: {
295:     double point_value = SymbolInfoDouble(_Symbol, SYMBOL_TRADE_TICK_VALUE);
296:     double lot_size = risk_amount / (sl_distance / symInfo.Point() * point_value);
