//+------------------------------------------------------------------+
//|                   XAUUSD Multi-TF Scalping EA v2.0               |
//|                  Multi-Timeframe + Cascade TP System              |
//+------------------------------------------------------------------+
#property copyright "MT5 Scalping System"
#property link      "https://www.mql5.com"
#property version   "2.00"
#property strict

#include <Trade\Trade.mqh>
#include <Trade\SymbolInfo.mqh>
#include <Trade\PositionInfo.mqh>

//--- Input Parameters
input double         RiskPercent = 15.0;              // Risk % per trade
input int            SL_Buffer = 150;                 // SL buffer in points (100-200)
input int            MagicNumber = 100001;            // Magic Number
input bool           UseTradeHours = true;            // Enable trading hours filter
input string         TradeHours1_Start = "11:00";     // Session 1 Start (GMT+7)
input string         TradeHours1_End = "16:00";       // Session 1 End (GMT+7)
input string         TradeHours2_Start = "16:00";     // Session 2 Start (GMT+7)
input string         TradeHours2_End = "02:00";       // Session 2 End (GMT+7)
input bool           AllowNewOrders = true;           // Allow new orders during hours
input bool           CloseOutsideHours = false;       // Close positions outside hours

//--- Global Variables
CTrade trade;
CPositionInfo posInfo;
CSymbolInfo symInfo;

struct TP_LEVEL {
    double RR;              // Risk-Reward ratio
    bool   Closed;          // Already closed this level
    double SL_Target;       // Target SL after hitting TP
};

TP_LEVEL tp_levels[5] = {
    {2.0, false, 0},        // RR 1:2
    {3.0, false, 0},        // RR 1:3
    {5.0, false, 0},        // RR 1:5
    {10.0, false, 0},       // RR 1:10
    {15.0, false, 0}        // RR 1:15
};

double g_initial_risk = 0;

//+------------------------------------------------------------------+
//| Expert initialization function                                   |
//+------------------------------------------------------------------+
int OnInit()
{
    trade.SetExpertMagicNumber(MagicNumber);
    trade.SetDeviationInPoints(10);

    if(!symInfo.Name(_Symbol)) {
        Print("Failed to get symbol info for: ", _Symbol);
        return INIT_FAILED;
    }
    symInfo.RefreshRates();

    return INIT_SUCCEEDED;
}

//+------------------------------------------------------------------+
//| Expert deinitialization function                                 |
//+------------------------------------------------------------------+
void OnDeinit(const int reason)
{
    Print("EA Stopped - Reason: ", reason);
}

//+------------------------------------------------------------------+
//| Reset TP Levels helper                                           |
//+------------------------------------------------------------------+
void ResetTPLevels()
{
    for(int i = 0; i < 5; i++) {
        tp_levels[i].Closed = false;
    }
}

//+------------------------------------------------------------------+
//| Expert tick function                                             |
//+------------------------------------------------------------------+
void OnTick()
{
    symInfo.RefreshRates();

    int open_count = CountOpenPositions();
    if(open_count == 0) {
        g_initial_risk = 0;
        ResetTPLevels();
    }

    // Check if we should trade based on time
    bool in_trade_hours = IsInTradingHours();

    // Update existing positions
    UpdateOpenPositions();

    // Only open new positions during trading hours
    if(in_trade_hours && AllowNewOrders) {
        CheckForSignal();
    }
}

//+------------------------------------------------------------------+
//| Check session helper                                             |
//+------------------------------------------------------------------+
bool IsTimeInSession(int current, int start, int end)
{
    if(start <= end)
        return (current >= start && current < end);
    else
        return (current >= start || current < end); // Midnight cross
}

//+------------------------------------------------------------------+
//| Check Trading Hours                                              |
//+------------------------------------------------------------------+
bool IsInTradingHours()
{
    if(!UseTradeHours) return true;

    MqlDateTime now;
    TimeToStruct(TimeCurrent() + 25200, now);  // GMT+7 (25200 = 7*3600)

    int current_time = now.hour * 60 + now.min; // total minutes from 00:00

    int start1 = StringToTime1(TradeHours1_Start) / 60;
    int end1   = StringToTime1(TradeHours1_End) / 60;
    int start2 = StringToTime1(TradeHours2_Start) / 60;
    int end2   = StringToTime1(TradeHours2_End) / 60;

    if(IsTimeInSession(current_time, start1, end1)) return true;
    if(IsTimeInSession(current_time, start2, end2)) return true;

    return false;
}

//+------------------------------------------------------------------+
//| Parse time string "HH:MM" into seconds                           |
//+------------------------------------------------------------------+
int StringToTime1(string time_str)
{
    string parts[];
    int count = StringSplit(time_str, ':', parts);
    if(count != 2) return 0;

    int hour = (int)StringToInteger(parts[0]);
    int min  = (int)StringToInteger(parts[1]);
    return (hour * 3600 + min * 60);
}

//+------------------------------------------------------------------+
//| Check for Entry Signal                                           |
//+------------------------------------------------------------------+
void CheckForSignal()
{
    // Check if already have an open position
    if(CountOpenPositions() > 0) return;

    // Check trend on Higher Timeframes
    int trend = GetTrendDirection();
    if(trend == 0) return;  // No clear trend

    // Check M5 confirmation (Bullish/Bearish Close)
    bool signal = false;
    int signal_type = 0;

    signal = GetM5ConfirmationSignal(signal_type);
    if(!signal) return;

    // Don't trade if trend and signal mismatch
    if((trend == 1 && signal_type != 1) || (trend == -1 && signal_type != -1)) return;

    // Execute trade
    ExecuteTrade(signal_type);
}

//+------------------------------------------------------------------+
//| Get Trend Direction from Higher Timeframes                       |
//+------------------------------------------------------------------+
int GetTrendDirection()
{
    // Check H4 trend (Candle 1 close vs open & HH/HL)
    double h4_close_1 = iClose(_Symbol, PERIOD_H4, 1);
    double h4_open_1  = iOpen(_Symbol, PERIOD_H4, 1);
    double h4_high_1  = iHigh(_Symbol, PERIOD_H4, 1);
    double h4_high_2  = iHigh(_Symbol, PERIOD_H4, 2);
    double h4_low_1   = iLow(_Symbol, PERIOD_H4, 1);
    double h4_low_2   = iLow(_Symbol, PERIOD_H4, 2);

    // Check H1 trend
    double h1_close_1 = iClose(_Symbol, PERIOD_H1, 1);
    double h1_open_1  = iOpen(_Symbol, PERIOD_H1, 1);

    // Check M30 trend
    double m30_close_1 = iClose(_Symbol, PERIOD_M30, 1);
    double m30_open_1  = iOpen(_Symbol, PERIOD_M30, 1);

    // Bullish alignment across H4, H1, M30
    bool h4_bull  = (h4_close_1 > h4_open_1) || (h4_high_1 > h4_high_2 && h4_low_1 > h4_low_2);
    bool h1_bull  = (h1_close_1 > h1_open_1);
    bool m30_bull = (m30_close_1 > m30_open_1);

    // Bearish alignment across H4, H1, M30
    bool h4_bear  = (h4_close_1 < h4_open_1) || (h4_high_1 < h4_high_2 && h4_low_1 < h4_low_2);
    bool h1_bear  = (h1_close_1 < h1_open_1);
    bool m30_bear = (m30_close_1 < m30_open_1);

    if(h4_bull && h1_bull && m30_bull) return 1;    // Uptrend
    if(h4_bear && h1_bear && m30_bear) return -1;  // Downtrend

    return 0; // No clear trend
}

//+------------------------------------------------------------------+
//| Get M5 Confirmation Signal                                       |
//+------------------------------------------------------------------+
bool GetM5ConfirmationSignal(int &signal_type)
{
    double m5_open  = iOpen(_Symbol, PERIOD_M5, 1);   // Previous closed candle
    double m5_close = iClose(_Symbol, PERIOD_M5, 1);

    // Bullish Close (Green Candle): Close > Open
    if(m5_close > m5_open) {
        signal_type = 1;  // Buy signal
        return true;
    }

    // Bearish Close (Red Candle): Close < Open
    if(m5_close < m5_open) {
        signal_type = -1; // Sell signal
        return true;
    }

    return false;
}

//+------------------------------------------------------------------+
//| Execute Trade                                                    |
//+------------------------------------------------------------------+
void ExecuteTrade(int trade_type)
{
    double entry_price, sl_price, tp5_price;

    // Get previous M5 candle low/high for SL
    double prev_m5_low  = iLow(_Symbol, PERIOD_M5, 1);
    double prev_m5_high = iHigh(_Symbol, PERIOD_M5, 1);

    // Current bid/ask
    double bid = SymbolInfoDouble(_Symbol, SYMBOL_BID);
    double ask = SymbolInfoDouble(_Symbol, SYMBOL_ASK);

    if(trade_type == 1) {  // BUY
        entry_price = ask;
        sl_price = prev_m5_low - (SL_Buffer * symInfo.Point());

        double risk = entry_price - sl_price;
        tp5_price = entry_price + (risk * 15.0); // TP5 (RR 1:15)

    } else {  // SELL
        entry_price = bid;
        sl_price = prev_m5_high + (SL_Buffer * symInfo.Point());

        double risk = sl_price - entry_price;
        tp5_price = entry_price - (risk * 15.0); // TP5 (RR 1:15)
    }

    // Store initial risk
    g_initial_risk = MathAbs(entry_price - sl_price);

    // Calculate lot size based on risk
    double account_balance = AccountInfoDouble(ACCOUNT_BALANCE);
    double risk_amount = account_balance * (RiskPercent / 100.0);
    double lot_size = CalculateLotSize(risk_amount, g_initial_risk);

    if(lot_size < symInfo.LotsMin()) {
        Print("Lot size too small: ", lot_size, " Min Lot: ", symInfo.LotsMin());
        return;
    }

    ResetTPLevels();

    // Open position
    if(trade_type == 1) {
        if(trade.Buy(lot_size, _Symbol, entry_price, sl_price, tp5_price, "XAUUSD Multi-TF Buy")) {
            Print("BUY Trade Opened - Entry: ", entry_price, " SL: ", sl_price, " TP5: ", tp5_price, " Lot: ", lot_size);
        } else {
            Print("Error opening BUY trade: ", trade.ResultRetcodeDescription());
        }
    } else {
        if(trade.Sell(lot_size, _Symbol, entry_price, sl_price, tp5_price, "XAUUSD Multi-TF Sell")) {
            Print("SELL Trade Opened - Entry: ", entry_price, " SL: ", sl_price, " TP5: ", tp5_price, " Lot: ", lot_size);
        } else {
            Print("Error opening SELL trade: ", trade.ResultRetcodeDescription());
        }
    }
}

//+------------------------------------------------------------------+
//| Calculate Lot Size                                               |
//+------------------------------------------------------------------+
double CalculateLotSize(double risk_amount, double sl_distance)
{
    if(sl_distance <= 0) return symInfo.LotsMin();

    double point_value = SymbolInfoDouble(_Symbol, SYMBOL_TRADE_TICK_VALUE);
    double point_size  = symInfo.Point();
    if(point_value <= 0 || point_size <= 0) return symInfo.LotsMin();

    double lot_size = risk_amount / ((sl_distance / point_size) * point_value);

    double lot_step = symInfo.LotsStep();
    if(lot_step > 0) {
        lot_size = MathFloor(lot_size / lot_step) * lot_step;
    }
    lot_size = NormalizeDouble(lot_size, 2);

    if(lot_size < symInfo.LotsMin()) lot_size = symInfo.LotsMin();
    if(lot_size > symInfo.LotsMax()) lot_size = symInfo.LotsMax();

    return lot_size;
}

//+------------------------------------------------------------------+
//| Update Open Positions                                            |
//+------------------------------------------------------------------+
void UpdateOpenPositions()
{
    for(int i = 0; i < PositionsTotal(); i++) {
        if(posInfo.SelectByIndex(i)) {
            if(posInfo.Magic() == MagicNumber && posInfo.Symbol() == _Symbol) {
                UpdatePositionTP_SL(posInfo.Ticket());
            }
        }
    }
}

//+------------------------------------------------------------------+
//| Update Position TP and SL                                        |
//+------------------------------------------------------------------+
void UpdatePositionTP_SL(ulong ticket)
{
    if(!posInfo.SelectByTicket(ticket)) return;

    double entry_price = posInfo.PriceOpen();
    double current_sl  = posInfo.StopLoss();
    double bid = SymbolInfoDouble(_Symbol, SYMBOL_BID);
    double ask = SymbolInfoDouble(_Symbol, SYMBOL_ASK);
    double current_price = (posInfo.PositionType() == POSITION_TYPE_BUY) ? bid : ask;

    // Calculate current profit
    double profit = 0;
    if(posInfo.PositionType() == POSITION_TYPE_BUY) {
        profit = current_price - entry_price;
    } else {
        profit = entry_price - current_price;
    }

    if(profit <= 0) return;  // No profit yet

    double risk = (g_initial_risk > 0) ? g_initial_risk : MathAbs(entry_price - current_sl);
    if(risk <= 0) return;

    // Check each TP level
    for(int i = 0; i < 5; i++) {
        double current_rr = profit / risk;

        if(current_rr >= tp_levels[i].RR && !tp_levels[i].Closed) {
            double new_sl = 0;
            if(posInfo.PositionType() == POSITION_TYPE_BUY) {
                new_sl = NormalizeDouble(entry_price + (profit * 0.5), symInfo.Digits());
                if(current_sl == 0 || new_sl > current_sl) {
                    if(trade.PositionModify(ticket, new_sl, posInfo.TakeProfit())) {
                        tp_levels[i].Closed = true;
                        Print("TP Level ", i+1, " (RR 1:", (int)tp_levels[i].RR, ") - SL moved to ", new_sl);
                    }
                }
            } else {
                new_sl = NormalizeDouble(entry_price - (profit * 0.5), symInfo.Digits());
                if(current_sl == 0 || new_sl < current_sl) {
                    if(trade.PositionModify(ticket, new_sl, posInfo.TakeProfit())) {
                        tp_levels[i].Closed = true;
                        Print("TP Level ", i+1, " (RR 1:", (int)tp_levels[i].RR, ") - SL moved to ", new_sl);
                    }
                }
            }
        }
    }
}

//+------------------------------------------------------------------+
//| Count Open Positions                                             |
//+------------------------------------------------------------------+
int CountOpenPositions()
{
    int count = 0;
    for(int i = 0; i < PositionsTotal(); i++) {
        if(posInfo.SelectByIndex(i)) {
            if(posInfo.Magic() == MagicNumber && posInfo.Symbol() == _Symbol) {
                count++;
            }
        }
    }
    return count;
}

