void ExecuteScalpTrade(int trade_type)
{
    double entry_price, sl_price, tp_price;
    double ask = SymbolInfoDouble(_Symbol, SYMBOL_ASK);
    double bid = SymbolInfoDouble(_Symbol, SYMBOL_BID);

    if(trade_type == 1) { // BUY
        entry_price = ask;
